import * as React from 'react';
import { graphql, useStaticQuery } from 'gatsby';
import { GatsbyImage } from 'gatsby-plugin-image';
import { Reveal } from '~src/components/utils/motion/Reveal';
import * as styles from './Clients.module.scss';
export const Clients = ()=>{
    const data = useStaticQuery(CLIENTS_LOGO_QUERY);
    return React.createElement("div", {
        className: styles.feed
    }, data.logos.nodes.map((client, i)=>React.createElement(Reveal, {
            as: "a",
            key: client.id,
            title: client.title,
            href: client.url,
            target: "_blank",
            rel: "noreferrer",
            delay: Math.min(i, 8) * 0.03
        }, React.createElement(GatsbyImage, {
            className: styles.logoImg,
            image: client.img.childImageSharp.gatsbyImageData,
            alt: client.title
        }))));
};
const CLIENTS_LOGO_QUERY = graphql`
  query LogoFiles {
    logos: allClientsYaml {
      nodes {
        title
        url
        id
        img {
          childImageSharp {
            gatsbyImageData(layout: CONSTRAINED, width: 200)
          }
        }
      }
    }
  }
`;
